package dev.martianzoo.tfm.text

import dev.martianzoo.pets.api.SystemClasses.CLASS
import dev.martianzoo.pets.api.SystemClasses.OWNED
import dev.martianzoo.pets.ast.ClassName
import dev.martianzoo.pets.ast.ClassName.Companion.cn
import dev.martianzoo.pets.ast.Expression
import dev.martianzoo.pets.ast.Metric
import dev.martianzoo.pets.ast.Property
import dev.martianzoo.pets.ast.Requirement
import dev.martianzoo.pets.types.Dependency.Key

internal data class MetricRendering(
    val phrase: NounPhrase,
    val ranking: Ranking = Ranking.MOST,
) {
  internal enum class Ranking {
    MOST,
    HIGHEST,
  }
}

internal fun renderMetricPhrase(metric: Metric, describers: Describers): NounPhrase? =
    renderMetric(metric, describers, possessorEstablished = false)?.phrase

/** Total pass-one metric boundary for a context that can retain a phrase-level refusal. */
internal fun lexicalizeMetricPhrase(metric: Metric, describers: Describers): NounPhrase =
    lexicalizeMetric(metric, describers, possessorEstablished = false).phrase

internal fun renderRequirementMetricPhrase(
    metric: Metric,
    count: Int,
    describers: Describers,
): NounPhrase? = renderMetric(metric, describers, possessorEstablished = true, count)?.phrase

/** Total ranked-metric boundary used by goal text. */
internal fun lexicalizeRankedMetricPhrase(metric: Metric, describers: Describers): NounPhrase {
  val rendering = lexicalizeMetric(metric, describers, possessorEstablished = true)
  return when (rendering.ranking) {
    MetricRendering.Ranking.MOST -> rendering.phrase.asPlural().withDeterminer(Determiner.MOST)
    MetricRendering.Ranking.HIGHEST -> rendering.phrase.withDeterminer(Determiner.HIGHEST)
  }
}

private fun lexicalizeMetric(
    metric: Metric,
    describers: Describers,
    possessorEstablished: Boolean,
): MetricRendering =
    renderMetric(metric, describers, possessorEstablished)
        ?: MetricRendering(NounPhrase.rawPets(Unresolved(metric, RefusalReason.UNSUPPORTED_METRIC)))

private fun renderMetric(
    metric: Metric,
    describers: Describers,
    possessorEstablished: Boolean,
    count: Int? = null,
): MetricRendering? {
  return when (metric) {
    is Metric.Count ->
        describers.recognizeCountedExpression(metric.expression, count, possessorEstablished)
    is Metric.Scaled -> renderScaledCountPhrase(metric, describers, possessorEstablished)
    is Metric.Max -> {
      renderMatchedTagPair(metric, describers, possessorEstablished, count)
          ?: (metric.maximum as? Metric.Constant)?.value?.let { maximum ->
            renderMetric(metric.inner, describers, possessorEstablished)?.let {
              it.copy(phrase = it.phrase.withModifier(Modifier.Parenthetical("max $maximum")))
            }
          }
    }
    is Metric.Or -> renderCombinedMetric(metric, describers, possessorEstablished, count)
    is Metric.Subtract ->
        if (
            (metric.subtrahend as? Metric.Count)?.expression?.let(describers::isProductionOffset) ==
                true
        ) {
          renderMetric(metric.minuend, describers, possessorEstablished, count)
        } else {
          val left =
              (metric.minuend as? Metric.Constant)?.let {
                MetricRendering(NounPhrase.text(it.value.toString()))
              } ?: renderMetric(metric.minuend, describers, possessorEstablished, count)
          val right =
              (metric.subtrahend as? Metric.Constant)?.let {
                MetricRendering(NounPhrase.text(it.value.toString()))
              } ?: renderMetric(metric.subtrahend, describers, possessorEstablished)
          if (
              left == null ||
                  right == null ||
                  metric.minuend is Metric.Subtract ||
                  metric.subtrahend is Metric.Subtract
          )
              null
          else if (metric.minuend is Metric.Constant)
              MetricRendering(
                  NounPhrase.text("unit")
                      .withModifier(
                          Modifier.Relation(
                              "by which",
                              right.phrase.withModifier(
                                  Modifier.Relation("falls short of", left.phrase)
                              ),
                          )
                      )
              )
          else
              left.copy(
                  phrase = left.phrase.withModifier(Modifier.Relation("in excess of", right.phrase))
              )
        }
    is Metric.Constant,
    is Metric.Eval,
    is Metric.Rank,
    is Metric.Transform,
    is Property -> null
  }
}

private fun renderMatchedTagPair(
    metric: Metric.Max,
    describers: Describers,
    possessorEstablished: Boolean,
    count: Int?,
): MetricRendering? {
  val first = (metric.inner as? Metric.Count)?.expression ?: return null
  val second = (metric.maximum as? Metric.Count)?.expression ?: return null
  if (!first.simple || !second.simple) return null
  val firstTag =
      describers.playedTagPhrase(first.className)?.noun()?.removeSuffix(" tag") ?: return null
  val secondTag =
      describers.playedTagPhrase(second.className)?.noun()?.removeSuffix(" tag") ?: return null
  val firstResolved = describers.resolveExpression(first) ?: return null
  val secondResolved = describers.resolveExpression(second) ?: return null
  if (firstResolved.sourceDependencies != secondResolved.sourceDependencies) return null
  if (firstResolved.sourceDependencies.isNotEmpty()) return null
  val pair =
      NounPhrase(
          "pair of $firstTag and $secondTag tags",
          "pairs of $firstTag and $secondTag tags",
          count = count,
      )
  return MetricRendering(pair.withOwnership("you have", possessorEstablished))
}

private fun renderCombinedMetric(
    metric: Metric.Or,
    describers: Describers,
    possessorEstablished: Boolean,
    count: Int?,
): MetricRendering? {
  val members =
      metric.metrics.map {
        renderMetric(it, describers, possessorEstablished) ?: return null
      }
  val ranking =
      if (members.all { it.ranking == MetricRendering.Ranking.HIGHEST }) {
        MetricRendering.Ranking.HIGHEST
      } else {
        MetricRendering.Ranking.MOST
      }
  val phrase =
      if (possessorEstablished) {
        val phrases = members.map { it.phrase.asPlural() }
        (factorSharedNounHead(phrases, Conjunction.AND)
                ?: NounPhrase.coordinated(Coordination(phrases, Conjunction.AND)))
            .let { if (count == null) it else it.quantified(count) }
            .withModifier(Modifier.Phrase("combined"))
      } else {
        NounPhrase.coordinated(Coordination(members.map { it.phrase }, Conjunction.OR))
      }
  return MetricRendering(phrase, ranking)
}

private fun renderScaledCountPhrase(
    metric: Metric.Scaled,
    describers: Describers,
    possessorEstablished: Boolean,
): MetricRendering? {
  val inner = metric.inner
  if (
      inner !is Metric.Count &&
          inner !is Metric.Or &&
          !(inner is Metric.Subtract &&
              inner.minuend is Metric.Count &&
              inner.subtrahend is Metric.Constant)
  )
      return null
  val rendered =
      if (inner is Metric.Or) {
        renderCombinedMetric(inner, describers, possessorEstablished = true, count = metric.unit)
      } else {
        renderMetric(metric.inner, describers, possessorEstablished, metric.unit)
      } ?: return null
  return if (inner is Metric.Count) rendered
  else
      rendered.copy(
          phrase =
              NounPhrase.text("complete set").withModifier(Modifier.Relation("of", rendered.phrase))
      )
}

/** The sole count-expression-to-noun-phrase lexicalization protocol. */
internal fun Describers.lexicalizeCountedExpression(
    expression: Expression,
    count: Int?,
    possessorEstablished: Boolean,
): MetricRendering =
    recognizeCountedExpression(expression, count, possessorEstablished)
        ?: unsupportedCountedExpression(expression)

private fun Describers.recognizeCountedExpression(
    expression: Expression,
    count: Int?,
    possessorEstablished: Boolean,
): MetricRendering? {
  val exclusion = expression.refinement as? Expression.Refinement.Not
  if (exclusion != null) {
    val included =
        recognizeCountedExpression(expression.copy(refinement = null), count, possessorEstablished)
            ?: return null
    val excluded =
        recognizeCountedExpression(exclusion.excluded, null, possessorEstablished = true)
            ?: return null
    return included.copy(
        phrase =
            included.phrase.withModifier(Modifier.Relation("excluding", excluded.phrase.asPlural()))
    )
  }
  val allResourceProduction = productionCategoryExpression(expression, this)
  if (
      expression.refinement == null &&
          allResourceProduction?.owner == null &&
          allResourceProduction?.resource == cn("StandardResource")
  ) {
    return MetricRendering(NounPhrase("production", count = count), MetricRendering.Ranking.HIGHEST)
  }
  countedProductionCategories(expression, this)?.let { productions ->
    if (productions.any { it.owner != null }) return null
    val resourceType = resolveExpression(expression)?.dependency(Key(cn("Production"), 0))
    if (resourceType?.representedClass?.className == cn("StandardResource")) {
      val allResources = expressions.concreteSubclassesOf(cn("StandardResource")).toSet()
      val selectedResources = productions.map(ProductionExpression::resource).toSet()
      val excluded = (allResources - selectedResources).singleOrNull()
      if (
          excluded != null &&
              allResources.containsAll(selectedResources) &&
              selectedResources.size == productions.size &&
              selectedResources.size + 1 == allResources.size
      ) {
        return MetricRendering(
            NounPhrase("production", count = count)
                .withModifier(Modifier.Relation("excluding", productionNounPhrase(excluded))),
            MetricRendering.Ranking.HIGHEST,
        )
      }
    }
    val productionPhrases = productions.map { production ->
      productionNounPhrase(production.resource)
    }
    val phrase =
        (factorSharedNounHead(productionPhrases, Conjunction.AND)
                ?: NounPhrase.coordinated(Coordination(productionPhrases, Conjunction.AND)))
            .let { if (count == null) it else it.quantified(count) }
            .withModifier(Modifier.Phrase("combined"))
    return MetricRendering(phrase, MetricRendering.Ranking.HIGHEST)
  }
  productionCategoryExpression(expression, this)?.let { production ->
    if (production.owner != null) return null
    return MetricRendering(
        productionNounPhrase(production.resource).copy(count = count),
        MetricRendering.Ranking.HIGHEST,
    )
  }
  scaleFrame(expression.className)
      ?.takeIf { expression.simple }
      ?.let { scale ->
        val subject =
            if (!possessorEstablished) scale.subject else scale.subject.removePrefix("your ")
        return MetricRendering(
            if (count == null) NounPhrase.text(subject)
            else
                NounPhrase("step", "steps", count = count)
                    .withModifier(Modifier.Relation("of", NounPhrase.text(subject))),
            MetricRendering.Ranking.HIGHEST,
        )
      }
  val agreementCount = count ?: 1
  renderCountedRelation(expression, this)?.let { relation ->
    return MetricRendering(relation.countedObject(count))
  }
  renderFilteredDistinctKinds(expression, count, possessorEstablished, this)?.let {
    return MetricRendering(it)
  }
  distinctOwnedKinds(expression, this)?.let { noun ->
    var phrase =
        NounPhrase(noun.singular, noun.plural, count = count)
            .withOwnership("you have", possessorEstablished)
    if (enteringCardHasTag(expression.arguments.single().className)) {
      phrase = phrase.withModifier(Modifier.Parenthetical("including this"))
    }
    return MetricRendering(phrase)
  }
  renderFilteredComponentCount(expression, count)?.let {
    return MetricRendering(it)
  }
  renderZeroMaximumFilter(expression, count)?.let {
    return MetricRendering(it)
  }
  renderComponentCount(expression, count)?.let {
    return MetricRendering(it)
  }
  renderFilteredPlacementCount(expression, count, possessorEstablished)?.let {
    return MetricRendering(it)
  }
  renderTagMetric(expression, count, possessorEstablished, this)?.let {
    return MetricRendering(it)
  }
  renderUnrestrictedOwnedComponent(expression, count)?.let {
    return MetricRendering(it)
  }
  if (expression.simple) {
    if (isStandardResource(expression.className)) {
      val noun = componentNounPhrase(expression.className, agreementCount).copy(count = count)
      return MetricRendering(noun.withOwnership("you have", possessorEstablished))
    }
    cardResourceNounPhrase(expression.className, agreementCount)?.let { noun ->
      return MetricRendering(
          noun.copy(count = count).withOwnership("you have", possessorEstablished)
      )
    }
    placementCountPhrase(expression, count, possessorEstablished)?.let { phrase ->
      return MetricRendering(phrase)
    }
    renderDeckLocationMetric(expression, count)?.let { phrase ->
      return MetricRendering(phrase)
    }
    fact(expression.className, ComponentDescriber::countNoun)?.let { noun ->
      return MetricRendering(NounPhrase(noun.singular, noun.plural, count = count))
    }
    return null
  }
  placementCountPhrase(expression, count, possessorEstablished)?.let { phrase ->
    return MetricRendering(phrase)
  }
  renderDeckLocationMetric(expression, count)?.let { phrase ->
    return MetricRendering(phrase)
  }
  val resolved = resolveCardResource(expression) ?: return null
  if (!cardResourceHasHolder(resolved, thisExpression) || expression.refinement != null) {
    return null
  }
  val noun = cardResourceNounPhrase(expression.className, agreementCount) ?: return null
  return MetricRendering(noun.copy(count = count).withModifier(Modifier.Phrase("on this card")))
}

private fun unsupportedCountedExpression(expression: Expression): MetricRendering =
    MetricRendering(NounPhrase.rawPets(Unresolved(expression, RefusalReason.UNSUPPORTED_METRIC)))

private fun Describers.renderFilteredPlacementCount(
    expression: Expression,
    count: Int?,
    possessorEstablished: Boolean,
): NounPhrase? {
  val refinement = expression.refinement as? Expression.Refinement.Has ?: return null
  val noun =
      placementCountPhrase(expression.copy(refinement = null), count, possessorEstablished)
          ?: return null
  val modifier =
      renderSpatialFilter(refinement.requirement, expression.className)
          ?: renderMetricFilter(expression.className, refinement.requirement)
          ?: return null
  val relation = (refinement.requirement as? Requirement.Counting)?.let(::countedExpression)
  if (
      relation != null &&
          relation.simple &&
          fact(relation.className, ComponentDescriber::spatialRelation) != null
  ) {
    val area = resolveExpression(relation)?.dependency(Key(relation.className, 1)) ?: return null
    val site = placementSite(area.className) ?: return null
    val areas =
        NounPhrase.plural(describedNoun(area.className, site.noun, 2)).withModifier(modifier)
    return noun.withModifier(Modifier.Relation("on", areas))
  }
  return noun.withModifier(modifier)
}

private fun Describers.renderFilteredComponentCount(
    expression: Expression,
    count: Int?,
): NounPhrase? {
  val requirements = expression.refinement?.hasRequirementsOrNull() ?: return null
  var noun = renderComponentCount(expression.copy(refinement = null), count) ?: return null
  requirements.forEach { requirement ->
    val modifier =
        renderMetricFilter(expression.className, requirement)
            ?: renderSpatialFilter(requirement, expression.className)
            ?: Modifier.Relation(
                "with",
                NounPhrase.rawPets(Unresolved(requirement, RefusalReason.UNSUPPORTED_METRIC)),
            )
    noun = noun.withModifier(modifier)
  }
  if (enteringCardCounts(expression)) {
    noun = noun.withModifier(Modifier.Parenthetical("including this"))
  }
  return noun
}

private fun Expression.Refinement.hasRequirementsOrNull(): List<Requirement>? =
    when (this) {
      is Expression.Refinement.Has -> listOf(requirement)
      is Expression.Refinement.And ->
          refinements.map { (it as? Expression.Refinement.Has)?.requirement ?: return null }
      is Expression.Refinement.Not -> null
    }

private fun Describers.renderMetricFilter(
    className: dev.martianzoo.pets.ast.ClassName,
    requirement: Requirement,
): Modifier? {
  cardCriterion(requirement)?.let { criterion ->
    if (criterion is CardCriterion.ResourceIcon) return null
    return cardCriterionModifier(criterion, singular = false, this)
  }

  val counting = requirement as? Requirement.Counting ?: return null
  val property = counting.metric as? Property ?: return null
  if (property.receiver != null) return null
  val frame = triggerFrame(className) as? ComponentDescriber.TriggerFrame.PlayCard
  val threshold =
      frame?.minimumProperties?.get(property.propertyName.value)
          as? ComponentDescriber.MinimumProperty.Threshold
  if (threshold == null) {
    val propertyName = property.propertyName.value
    if (placementSite(className) == null || propertyName.any { it !in 'a'..'z' }) return null
    val comparison =
        when (counting) {
          is Requirement.Min -> "at least"
          is Requirement.Max -> "at most"
          is Requirement.Exact -> "exactly"
        }
    return Modifier.Phrase("whose $propertyName is $comparison ${counting.target}")
  }
  return renderPropertyThreshold(threshold, counting)
}

private fun NounPhrase.withOwnership(
    ownership: String,
    possessorEstablished: Boolean,
): NounPhrase = if (possessorEstablished) this else withModifier(Modifier.Phrase(ownership))

private fun Describers.renderUnrestrictedOwnedComponent(
    expression: Expression,
    count: Int?,
): NounPhrase? {
  if (expression.refinement != null) return null
  if (changeFrame(expression.className) != null) return null
  val resolved = resolveExpression(expression) ?: return null
  val ownerKey = Key(OWNED, 0)
  if (!resolved.hasOnlySourceDependency(ownerKey, anyoneExpression)) return null
  return componentNounPhrase(expression.className, count ?: 1)
      .copy(count = count)
      .withModifier(Modifier.Phrase("in play"))
}

internal fun distinctOwnedKinds(
    expression: Expression,
    describers: Describers,
): ComponentDescriber.Noun.Counted? {
  if (expression.className != CLASS || expression.refinement is Expression.Refinement.Not) {
    return null
  }
  val classKey = Key(CLASS, 0)
  val resolvedClass = describers.resolveExpression(expression) ?: return null
  val kind = resolvedClass.sourceDependency(classKey) ?: return null
  if (!resolvedClass.hasOnlySourceDependency(classKey, kind) || !kind.simple) return null
  val refinement = expression.refinement as? Expression.Refinement.Has ?: return null
  val minimum = refinement.requirement as? Requirement.Min ?: return null
  if (minimum.target != 1) return null
  val member = (minimum.metric as? Metric.Count)?.expression ?: return null
  val resolvedMember = describers.resolveExpression(member) ?: return null
  val ownerKey = Key(OWNED, 0)
  if (
      member.className != kind.className ||
          !(resolvedMember.sourceDependencies.isEmpty() ||
              resolvedMember.hasOnlySourceDependency(ownerKey, describers.ownerExpression)) ||
          member.refinement != null
  ) {
    return null
  }
  return describers.fact(kind.className, ComponentDescriber::distinctKinds)
}

private fun renderFilteredDistinctKinds(
    expression: Expression,
    count: Int?,
    possessorEstablished: Boolean,
    describers: Describers,
): NounPhrase? {
  val refinements =
      (expression.refinement as? Expression.Refinement.And)?.refinements ?: return null
  val member =
      refinements.firstNotNullOfOrNull { refinement ->
        distinctOwnedKinds(expression.copy(refinement = refinement), describers)?.let {
          refinement to it
        }
      } ?: return null
  var phrase =
      NounPhrase(member.second.singular, member.second.plural, count = count)
          .withOwnership("you have", possessorEstablished)
  val kind = expression.arguments.singleOrNull()?.className ?: return null
  refinements
      .filterNot { it === member.first }
      .forEach { refinement ->
        val requirement = (refinement as? Expression.Refinement.Has)?.requirement ?: return null
        phrase =
            phrase.withModifier(
                describers.renderMetricFilter(kind, requirement)
                    ?: Modifier.Relation(
                        "with",
                        NounPhrase.rawPets(
                            Unresolved(requirement, RefusalReason.UNSUPPORTED_METRIC)
                        ),
                    )
            )
      }
  return phrase
}

private fun Describers.renderComponentCount(
    expression: Expression,
    count: Int?,
): NounPhrase? {
  if (expression.refinement != null) return null
  val description = metricCount(expression.className) ?: return null
  val resolved = resolveExpression(expression) ?: return null
  val ownerKey = Key(OWNED, 0)
  val cardBackKey = Key(cn("CardFront"), 0)
  val category =
      if (
          expression.className == cn("CardFront") &&
              resolved.sourceDependencies.keys == setOf(cardBackKey)
      )
          resolved.sourceDependency(cardBackKey)?.let(::representedClassArgument)
      else null
  val suffix =
      when {
        resolved.sourceDependencies.isEmpty() -> description.unqualifiedSuffix
        resolved.hasOnlySourceDependency(ownerKey, anyoneExpression) -> description.anyoneSuffix
        category != null -> description.unqualifiedSuffix
        else -> return null
      } ?: return null
  val categoryNoun = category?.let { fact(it.className, ComponentDescriber::countNoun) }
  val nounType = categoryNoun ?: description.noun
  val noun = NounPhrase(nounType.singular, nounType.plural, count = count)
  return if (suffix.isEmpty()) noun else noun.withModifier(Modifier.Phrase(suffix))
}

private fun Describers.renderZeroMaximumFilter(
    expression: Expression,
    count: Int?,
): NounPhrase? {
  val resolved = resolveExpression(expression) ?: return null
  if (resolved.sourceDependencies.isNotEmpty()) return null
  val outer = fact(expression.className, ComponentDescriber::countNoun) ?: return null
  val refinement = expression.refinement as? Expression.Refinement.Has ?: return null
  val maximum = refinement.requirement as? Requirement.Max ?: return null
  if (maximum.target != 0) return null
  val excluded = (maximum.metric as? Metric.Count)?.expression ?: return null
  if (!excluded.simple) return null
  val inner = fact(excluded.className, ComponentDescriber::countNoun) ?: return null
  var noun =
      NounPhrase(outer.singular, outer.plural, count = count)
          .withModifier(
              Modifier.Relation(
                  "with",
                  NounPhrase(
                      inner.singular,
                      inner.plural,
                      determiner = Determiner.NO,
                      grammaticalNumber = NounPhrase.GrammaticalNumber.PLURAL,
                  ),
              )
          )
  if (enteringCardCounts(expression)) {
    noun = noun.withModifier(Modifier.Parenthetical("including this"))
  }
  return noun
}

private fun renderTagMetric(
    expression: Expression,
    count: Int?,
    possessorEstablished: Boolean,
    describers: Describers,
): NounPhrase? {
  if (expression.refinement != null) return null
  val noun = describers.tagNoun(expression.className) ?: return null
  val resolved = describers.resolveExpression(expression) ?: return null
  val ownerKey = Key(OWNED, 0)
  val (ownership, includesCurrentCard) =
      when {
        resolved.sourceDependencies.isEmpty() -> "you have" to true
        resolved.hasOnlySourceDependency(ownerKey, describers.anyoneExpression) -> null to true
        resolved.sourceDependencies.size == 1 &&
            resolved.sourceDependency(ownerKey)?.let(describers::isNotOwner) == true ->
            "your opponents have" to false
        else -> return null
      }
  val nounPhrase = NounPhrase(noun.singular, noun.plural, count = count)
  var phrase =
      if (ownership == null) {
        nounPhrase.withModifier(Modifier.Phrase("in play"))
      } else {
        nounPhrase.withOwnership(ownership, possessorEstablished)
      }
  if (includesCurrentCard && describers.enteringCardHasTag(expression.className)) {
    phrase = phrase.withModifier(Modifier.Parenthetical("including this"))
  }
  return phrase
}

private fun Describers.placementCountPhrase(
    expression: Expression,
    count: Int?,
    possessorEstablished: Boolean,
): NounPhrase? {
  if (expression.refinement != null) return null
  val placement = positionedFrame(expression.className) ?: return null
  val resolved = resolveExpression(expression) ?: return null
  val ownerKey = Key(OWNED, 0)
  val ownerType = resolved.dependency(ownerKey) ?: return null
  val site =
      resolved.type.rootClass.dependencies.keys
          .mapNotNull { key ->
            resolved.selectedDependency(key)?.takeIf {
              placementSite(it.rootClass.className) != null
            }
          }
          .singleOrNull()
  val explicitlyUnrestricted = resolved.sourceDependency(ownerKey) == anyoneExpression
  val ownedByYou =
      !explicitlyUnrestricted &&
          (resolved.sourceDependency(ownerKey) == null ||
              resolved.sourceDependency(ownerKey) == ownerExpression ||
              isGameParticipant(ownerType.rootClass.className))
  val (owner, location) =
      when {
        ownedByYou && site == null -> (placement.unqualifiedOwnership ?: return null) to null
        ownedByYou && site != null ->
            (placement.unqualifiedOwnership ?: return null) to
                (renderPlacementLocation(site.expression) ?: return null)
        explicitlyUnrestricted && site == null -> (placement.anyoneOwnership ?: return null) to null
        explicitlyUnrestricted && site != null ->
            (placement.anyoneOwnership ?: return null) to
                (renderPlacementLocation(site.expression) ?: return null)
        else -> null
      } ?: return null
  val ownerPhrase =
      if (!possessorEstablished) {
        when (owner) {
          ComponentDescriber.OwnershipPhrase.IMPLICIT -> null
          ComponentDescriber.OwnershipPhrase.YOURS -> "you own"
          ComponentDescriber.OwnershipPhrase.ANYONES -> "anyone owns"
        }
      } else {
        null
      }
  val referenceNoun = placement.referenceNoun ?: placement.noun
  val determiner = null
  val noun = NounPhrase(referenceNoun.singular, referenceNoun.plural, count, determiner)
  return listOfNotNull(
          ownerPhrase?.let(Modifier::Phrase),
          Modifier.Phrase("in play").takeIf { explicitlyUnrestricted },
          location,
      )
      .fold(noun, NounPhrase::withModifier)
}

private fun Describers.renderPlacementLocation(expression: Expression): Modifier? {
  if (expression.refinement is Expression.Refinement.Not) return null
  if (expression.simple) {
    fact(expression.className, ComponentDescriber::metricLocation)?.let {
      return Modifier.Phrase(it)
    }
  }
  val site = placementSite(expression.className) ?: return null
  val namedSite =
      fact(expression.className, ComponentDescriber::noun) as? ComponentDescriber.Noun.Fixed
  val noun =
      if (concrete(expression.className) && namedSite != null) NounPhrase.text(namedSite.text)
      else
          when (val described = site.noun) {
            is ComponentDescriber.Noun.Counted -> NounPhrase.plural(described.plural)
            is ComponentDescriber.Noun.Fixed -> NounPhrase.text(described.text)
            ComponentDescriber.Noun.ClassName ->
                NounPhrase.plural(componentNoun(expression.className, 2))
          }
  val authoredRefinement = expression.refinement ?: return Modifier.Relation(site.relation, noun)
  val refinement = authoredRefinement as? Expression.Refinement.Has ?: return null
  val modifier =
      renderSpatialFilter(refinement.requirement, expression.className)
          ?: renderMetricFilter(expression.className, refinement.requirement)
          ?: Modifier.Relation(
              "that have",
              NounPhrase.rawPets(
                  Unresolved(refinement.requirement, RefusalReason.UNSUPPORTED_METRIC)
              ),
          )
  return Modifier.Relation(site.relation, noun.withModifier(modifier))
}

private fun Describers.renderSpatialFilter(
    requirement: Requirement,
    contextClass: ClassName,
): Modifier? {
  val counting = requirement as? Requirement.Counting ?: return null
  val expression = (counting.metric as? Metric.Count)?.expression ?: return null
  val relation = fact(expression.className, ComponentDescriber::spatialRelation)
  if (relation == null) {
    val positioned = positionedFrame(expression.className) ?: return null
    if (
        counting !is Requirement.Max ||
            counting.maximum != 0 ||
            expression.arguments.isNotEmpty() ||
            expression.refinement != null
    ) {
      return null
    }
    return Modifier.Relation(
        "with",
        NounPhrase(
            positioned.noun.singular,
            positioned.noun.plural,
            determiner = Determiner.NO,
            grammaticalNumber = NounPhrase.GrammaticalNumber.PLURAL,
        ),
    )
  }
  val targetExpression = expression.arguments.singleOrNull()
  val resolved = resolveExpression(expression) ?: return null
  val sourceType = resolved.dependency(Key(expression.className, 0))
  val countsAdjacentAreas =
      targetExpression == null &&
          sourceType != null &&
          isSubtypeOf(contextClass, sourceType.rootClass.className)
  val targetNoun =
      if (targetExpression != null) {
        spatialTarget(targetExpression, counting.target) ?: return null
      } else if (countsAdjacentAreas) {
        val target = resolved.dependency(Key(expression.className, 1)) ?: return null
        val noun = placementSite(target.rootClass.className)?.noun ?: return null
        NounPhrase.plural(describedNoun(target.rootClass.className, noun, 2))
      } else {
        relation.defaultTarget?.let { NounPhrase.plural(it.plural) } ?: return null
      }
  if (countsAdjacentAreas) {
    val adjacent =
        targetNoun.withAttributiveModifier(NounPhrase.text("adjacent")).quantified(counting.target)
    return Modifier.Relation(
        when (counting) {
          is Requirement.Min -> "with at least"
          is Requirement.Max -> "with at most"
          is Requirement.Exact -> "with exactly"
        },
        adjacent,
    )
  }
  return when (counting) {
    is Requirement.Min ->
        Modifier.Relation("${relation.phrase} at least", targetNoun.quantified(counting.target))
    is Requirement.Max ->
        if (counting.target == 0) {
          Modifier.Relation(
              relation.phrase,
              targetNoun.asPlural().withDeterminer(Determiner.NO),
          )
        } else {
          Modifier.Relation(relation.phrase, targetNoun.quantified(counting.target).atMost())
        }
    is Requirement.Exact ->
        Modifier.Relation(relation.phrase, targetNoun.quantified(counting.target))
  }
}

private fun Describers.spatialTarget(expression: Expression, count: Int): NounPhrase? {
  if (expression.refinement != null) return null
  positionedFrame(expression.className)?.let { placement ->
    val resolved = resolveExpression(expression) ?: return null
    val ownerKey = Key(OWNED, 0)
    if (resolved.sourceDependencies.keys.any { it != ownerKey }) return null
    val noun = placement.referenceNoun ?: placement.noun
    if (
        resolved.hasOnlySourceDependency(ownerKey, ownerExpression) ||
            (resolved.sourceDependencies.isEmpty() &&
                placement.unqualifiedOwnership == ComponentDescriber.OwnershipPhrase.YOURS)
    ) {
      return NounPhrase("${noun.singular} you own", "${noun.plural} you own", count = count)
    }
    return NounPhrase(noun.singular, noun.plural, count = count)
  }
  val site = placementSite(expression.className) ?: return null
  return when (val noun = site.noun) {
    is ComponentDescriber.Noun.Counted -> NounPhrase(noun.singular, noun.plural, count = count)
    is ComponentDescriber.Noun.Fixed -> NounPhrase(noun.text, count = count)
    ComponentDescriber.Noun.ClassName -> componentNounPhrase(expression.className, count)
  }
}

private fun Describers.renderDeckLocationMetric(
    expression: Expression,
    count: Int?,
): NounPhrase? {
  if (expression.refinement != null) return null
  if (changeFrame(expression.className) != ComponentDescriber.ChangeFrame.Deck) return null
  val resolved = resolveExpression(expression) ?: return null
  val location =
      resolved.sourceDependencies.values
          .mapNotNull { dependency ->
            if (!dependency.simple) return@mapNotNull null
            fact(dependency.className, ComponentDescriber::metricLocation)
          }
          .ifEmpty { listOfNotNull(fact(expression.className, ComponentDescriber::metricLocation)) }
  if (location.size != 1) return null
  return componentNounPhrase(expression.className, count ?: 1)
      .copy(count = count)
      .withModifier(Modifier.Phrase(location.single()))
}
